---- MONITORS ----
------------------
-- Written by Waterbear from your choices in the menu (Monitors): left → right order and
-- which workspaces go on which monitor. With nothing chosen, Hyprland places them itself.
require("monitors")

-------------------
---- AUTOSTART ----
-------------------
hl.on("hyprland.start", function()
    -- Login screen: when greetd started this session, lock with hyprlock before anything shows
    hl.exec_cmd([[[ -n "$WATERBEAR_LOCK_ON_START" ] && hyprlock --immediate-render]])
    hl.exec_cmd("systemctl --user start hyprpolkitagent")
    -- Dark mode for GTK apps (Thunar, file pickers) and anything that follows the system theme (Firefox)
    hl.exec_cmd("gsettings set org.gnome.desktop.interface color-scheme prefer-dark")
    hl.exec_cmd("gsettings set org.gnome.desktop.interface gtk-theme Adwaita-dark")
    hl.exec_cmd("swaync")                                   -- notifications + panel (Super+Shift+N)
    hl.exec_cmd("~/.local/bin/waterbear-wallpaper")                -- background (solid / image / live)
    hl.exec_cmd("~/.local/bin/waterbear-bar")                      -- status bar, if one was chosen (Super+W)
    hl.exec_cmd("hypridle")                                 -- idle lock / screen off / suspend
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
    hl.exec_cmd("[ -x ~/.local/bin/weekly-snapshot-login.sh ] && ~/.local/bin/weekly-snapshot-login.sh")  -- weekly snapshot (if enabled)
    hl.exec_cmd([[kitty sh -c 'fastfetch; exec "$SHELL"']])  -- open a terminal with fastfetch on login
end)

