-- Palette (@@SCHEME_NAME@@): background #@@BG@@ · accent #@@A@@ · accent 2 #@@B@@ · borders #@@C8@@
hl.config({
    general = {
        gaps_in  = 4,
        gaps_out = 10,
        border_size = 2,
        col = {
            active_border   = { colors = {"rgba(@@A@@ff)", "rgba(@@B@@ff)"}, angle = 45 },
            inactive_border = "rgba(@@C8@@aa)",
        },
        resize_on_border = false,
        allow_tearing = false,
        layout = "dwindle",
    },

    decoration = {
        rounding       = 4,
        rounding_power = 2,
        active_opacity   = 1.0,
        inactive_opacity = 0.92,

        -- Outer neon halo: a cyan shadow instead of a dark one
        shadow = {
            enabled      = true,
            range        = 14,
            render_power = 2,
            color        = 0x55@@A@@,   -- 0xAARRGGBB
            color_inactive = 0x00000000,
        },

        -- Inner glow (new in 0.55)
        glow = {
            enabled      = true,
            range        = 8,
            render_power = 3,
            color        = 0x33@@B@@,
            color_inactive = 0x00000000,
        },

        blur = {
            enabled  = true,
            size     = 4,
            passes   = 2,
            vibrancy = 0.17,
        },
    },

    animations = {
        enabled = true,
    },
})

-- Snappy animations
hl.curve("easeOutQuint", { type = "bezier", points = { {0.23, 1},  {0.32, 1} } })
hl.curve("linear",       { type = "bezier", points = { {0, 0},     {1, 1}    } })
hl.curve("almostLinear", { type = "bezier", points = { {0.5, 0.5}, {0.75, 1} } })
hl.curve("quick",        { type = "bezier", points = { {0.15, 0},  {0.1, 1}  } })

hl.animation({ leaf = "global",     enabled = true, speed = 10,   bezier = "default" })
hl.animation({ leaf = "border",     enabled = true, speed = 5,    bezier = "easeOutQuint" })
hl.animation({ leaf = "windows",    enabled = true, speed = 4,    bezier = "easeOutQuint" })
hl.animation({ leaf = "windowsIn",  enabled = true, speed = 3,    bezier = "easeOutQuint", style = "popin 90%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 1.5,  bezier = "linear",       style = "popin 90%" })
hl.animation({ leaf = "fade",       enabled = true, speed = 3,    bezier = "quick" })
hl.animation({ leaf = "layers",     enabled = true, speed = 3.5,  bezier = "easeOutQuint" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 2,    bezier = "almostLinear", style = "slide" })

hl.config({
    dwindle = { preserve_split = true },
})

