---- KEYBINDINGS ----
---------------------
require("binds")

-- Waterbear system menu (works with either keybind set)
hl.bind("SUPER + ALT + space", hl.dsp.exec_cmd("kitty --class waterbear-menu -e waterbear"))

----------------------
---- WINDOW RULES ----
----------------------
hl.window_rule({
    name  = "suppress-maximize-events",
    match = { class = ".*" },
    suppress_event = "maximize",
})

hl.window_rule({
    name  = "fix-xwayland-drags",
    match = { class = "^$", title = "^$", xwayland = true, float = true, fullscreen = false, pin = false },
    no_focus = true,
})

-- Dropdown terminal (Super+Shift+Enter) lives on its own special workspace
hl.window_rule({
    name  = "dropterm",
    match = { class = "^dropterm$" },
    float = true,
    size  = { "monitor_w*0.7", "monitor_h*0.45" },
    move  = { "monitor_w*0.15", "monitor_h*0.03" },
    workspace = "special:dropterm silent",
})

-- Keybind cheat sheet (Super+H)
hl.window_rule({
    name   = "keyhelp",
    match  = { class = "^keyhelp$" },
    float  = true,
    size   = { "monitor_w*0.6", "monitor_h*0.7" },
    center = true,
})

-- Small utility windows float
hl.window_rule({
    name  = "float-utils",
    match = { class = "^(pavucontrol|nm-connection-editor|blueman-manager|swappy|org.pulseaudio.pavucontrol)$" },
    float = true,
    center = true,
})

-- Waterbear menu and theme picker open as centered floating terminals
hl.window_rule({
    name   = "waterbear-menu",
    match  = { class = "^waterbear-menu$" },
    float  = true,
    size   = { "monitor_w*0.5", "monitor_h*0.6" },
    center = true,
})

-- Screensaver: fullscreen terminal (any input closes it, then the lock screen shows)
hl.window_rule({
    name       = "waterbear-screensaver",
    match      = { class = "^waterbear-screensaver$" },
    fullscreen = true,
})

